    async function syncAdminEmailsFromCloud() {
      try {
        if (typeof callGasApi !== "function") return;
        const currentList = getAdminEmails();
        const queryEmail = (typeof currentUser !== "undefined" && currentUser && currentUser.email) ? currentUser.email : (currentList[0] || ROOT_ADMIN_EMAIL);
        const res = await callGasApi("adminGetSettings", { adminEmail: queryEmail });
        if (res && res.success && res.settings) {
          const curSettings = getGeneralSettings();
          const isRecentlySavedLocally = curSettings._lastSavedAt && (Date.now() - curSettings._lastSavedAt < 300000);
          let hasSettingsChange = false;

          // 1. Marquee / Ticker text
          const cloudTicker = res.settings.tickerText || res.settings.TICKER_TEXT;
          if (cloudTicker !== undefined && cloudTicker !== null && cloudTicker.trim()) {
            if (!isRecentlySavedLocally && cloudTicker.trim() !== (curSettings.marqueeText || "").trim()) {
              curSettings.marqueeText = cloudTicker.trim();
              hasSettingsChange = true;
              if (typeof syncMarqueeNotice === "function") syncMarqueeNotice(curSettings.marqueeText);
            }
          }

          // 2. Hotline / Zalo
          const cloudHotline = res.settings.hotline || res.settings.HOTLINE;
          if (cloudHotline !== undefined && cloudHotline !== null && cloudHotline.trim()) {
            if (!isRecentlySavedLocally && cloudHotline.trim() !== (curSettings.hotline || "").trim()) {
              curSettings.hotline = cloudHotline.trim();
              hasSettingsChange = true;
              if (typeof syncZaloLinks === "function") syncZaloLinks(curSettings.hotline);
              if (document.getElementById("setHotline")) document.getElementById("setHotline").value = curSettings.hotline;
            }
          }

          // 3. Telegram
          const cloudTelegram = res.settings.telegram || res.settings.TELEGRAM;
          if (cloudTelegram !== undefined && cloudTelegram !== null && cloudTelegram.trim()) {
            if (!isRecentlySavedLocally && cloudTelegram.trim() !== (curSettings.telegram || "").trim()) {
              curSettings.telegram = cloudTelegram.trim();
              hasSettingsChange = true;
              if (typeof syncTelegramLinks === "function") syncTelegramLinks(curSettings.telegram);
              if (document.getElementById("setTelegram")) document.getElementById("setTelegram").value = curSettings.telegram;
            }
          }

          // 4. Site Name
          const cloudSiteName = res.settings.siteName || res.settings.SITE_NAME;
          if (cloudSiteName !== undefined && cloudSiteName !== null && cloudSiteName.trim()) {
            if (!isRecentlySavedLocally && cloudSiteName.trim() !== (curSettings.siteName || "").trim()) {
              curSettings.siteName = cloudSiteName.trim();
              hasSettingsChange = true;
              if (typeof applyBrandCustomizations === "function") applyBrandCustomizations(curSettings);
              if (document.getElementById("setSiteName")) document.getElementById("setSiteName").value = curSettings.siteName;
            }
          }

          if (hasSettingsChange) {
            localStorage.setItem("mmo_system_settings", JSON.stringify(curSettings));
            localStorage.setItem("mmo_general_settings", JSON.stringify(curSettings));
          }

          // 5. Admin Emails
          if (res.settings.adminEmails) {
            let cloudEmails = res.settings.adminEmails.split(",").map(e => (e || "").trim().toLowerCase()).filter(Boolean);
            if (cloudEmails.length > 0) {
              // Đảm bảo ROOT_ADMIN_EMAIL luôn có trong danh sách
              const rootEmail = (ROOT_ADMIN_EMAIL || "").toLowerCase().trim();
              if (rootEmail && !cloudEmails.includes(rootEmail)) {
                cloudEmails.unshift(rootEmail);
              }
              localStorage.setItem("mmo_admin_emails", JSON.stringify(cloudEmails));
              if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
              
              if (typeof currentUser !== "undefined" && currentUser && currentUser.email) {
                const myEmail = currentUser.email.toLowerCase().trim();
                if (!cloudEmails.includes(myEmail)) {
                  currentUser.role = "Thành Viên";
                  localStorage.setItem("mmo_user", JSON.stringify(currentUser));
                  if (typeof updateUserUI === "function") updateUserUI();
                  const curView = localStorage.getItem("mmo_current_view");
                  if (curView === "viewAdmin" && typeof switchView === "function") {
                    showToast("⚠️ Tài khoản của bạn đã bị rút quyền Quản Trị Viên!", "warning");
                    switchView("viewStore");
                  }
                }
              }
            }
          }
        }
      } catch(e) {
        console.warn("syncAdminEmailsFromCloud error:", e);
      }
    }
    window.syncAdminEmailsFromCloud = syncAdminEmailsFromCloud;

    function isAdminUser(user) {
      if (!user) {
        if (typeof currentUser !== "undefined" && currentUser) {
          user = currentUser;
        } else {
          try {
            const stored = localStorage.getItem("mmo_user");
            if (stored) user = JSON.parse(stored);
          } catch(e) {}
        }
      }
      if (!user || !user.email) return false;
      
      const userEmail = (user.email || "").toLowerCase().trim();
      const adminList = (typeof getAdminEmails === "function") ? getAdminEmails().map(e => (e || "").toLowerCase().trim()) : [];
      if (adminList.includes(userEmail)) return true;

      // Nếu người dùng không nằm trong danh sách Admin Email, tự động hạ quyền thành Thành Viên
      if (user.role === "Quản Trị Viên" || user.role === "ADMIN" || user.role === "Admin") {
        user.role = "Thành Viên";
        if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === userEmail) {
          currentUser.role = "Thành Viên";
          try { localStorage.setItem("mmo_user", JSON.stringify(currentUser)); } catch(e) {}
          if (typeof updateUserUI === "function") updateUserUI();
        }
      }

      return false;
    }
    window.isAdminUser = isAdminUser;

    function handleAddAdminEmail() {
      const input = document.getElementById("newAdminEmailInput");
      const email = (input?.value || "").trim().toLowerCase();
      if (!email || !email.includes("@")) {
        showToast("Vui lòng nhập địa chỉ email hợp lệ!", "warning");
        return;
      }
      const list = getAdminEmails();
      if (list.map(e => (e || "").toLowerCase().trim()).includes(email)) {
        showToast("Email này đã có trong danh sách quản trị!", "warning");
        return;
      }
      list.push(email);
      saveAdminEmails(list);

      // Auto update role in registered users list or add as new admin member
      let users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === email);
      if (uIdx !== -1) {
        users[uIdx].role = "Quản Trị Viên";
      } else {
        const newUserObj = {
          name: email.split("@")[0],
          email: email,
          role: "Quản Trị Viên",
          balance: 0,
          created: new Date().toLocaleDateString("vi-VN"),
          avatar: "https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email)
        };
        users.unshift(newUserObj);
      }
      saveRegisteredUsers(users);

      if (currentUser && (currentUser.email || "").toLowerCase().trim() === email) {
        currentUser.role = "Quản Trị Viên";
        try {
          localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        } catch(e) {}
        updateUserUI();
      }

      if (input) input.value = "";
      if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
      if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      if (typeof renderAdminDashboard === "function") renderAdminDashboard();
      
      showToast("🎉 Đã cấp quyền Quản Trị Viên thành công cho: " + email, "success");
    }
    window.handleAddAdminEmail = handleAddAdminEmail;

    function handleRemoveAdminEmail(email) {
      const targetEmail = (email || "").toLowerCase().trim();
      
      // ROOT ADMIN không thể bị xóa
      if (targetEmail === (ROOT_ADMIN_EMAIL || "").toLowerCase().trim()) {
        showToast("⛔ Không thể xóa tài khoản Quản Trị Viên gốc!", "error");
        return;
      }
      
      let list = getAdminEmails();
      if (list.length <= 1) {
        showToast("⚠️ Hệ thống phải duy trì ít nhất 1 Quản Trị Viên!", "warning");
        return;
      }
      if (!confirm("⚠️ Bạn có chắc muốn XÓA quyền Quản Trị Viên của [" + email + "]?")) return;
      
      list = list.filter(e => (e || "").toLowerCase().trim() !== targetEmail);
      saveAdminEmails(list);

      // Downgrade role in registered users
      let users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === targetEmail);
      if (uIdx !== -1) {
        users[uIdx].role = "Thành Viên";
        saveRegisteredUsers(users);
      }

      if (currentUser && (currentUser.email || "").toLowerCase().trim() === targetEmail) {
        currentUser.role = "Thành Viên";
        try {
          localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        } catch(e) {}
        updateUserUI();
        showToast("Tài khoản của bạn đã bị gỡ quyền Quản Trị Viên!", "warning");
        if (typeof switchView === "function") switchView("viewStore");
      }

      if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
      if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      if (typeof renderAdminDashboard === "function") renderAdminDashboard();
      
      showToast("🗑️ Đã xóa quyền Quản Trị Viên của: " + email, "success");
    }
    window.handleRemoveAdminEmail = handleRemoveAdminEmail;

    function renderAdminEmailsList() {
      const container = document.getElementById("adminEmailsListContainer") || document.getElementById("adminEmailsListBody");
      if (!container) return;
      const list = getAdminEmails();
      const canDelete = list.length > 1;
      container.innerHTML = list.map(email => {
        return `
          <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; background:#070a12; border:1px solid #1e293b; border-radius:8px; margin-bottom:8px;">
            <div style="display:flex; align-items:center; gap:10px;">
              <i class="fa-solid fa-user-shield" style="color:#10b981; font-size:1.1rem;"></i>
              <div>
                <strong style="color:#fff; font-size:0.88rem;">${escapeHtml(email)}</strong>
                <span style="font-size:0.75rem; color:#94a3b8; display:block;">Quản Trị Viên</span>
              </div>
            </div>
            ${canDelete ? `<button class="btn-copy-small" onclick="handleRemoveAdminEmail('${escapeHtml(email)}')" style="color:#ef4444; border-color:rgba(239,68,68,0.3); background:rgba(239,68,68,0.08); padding:4px 10px; cursor:pointer; font-weight:600; border-radius:6px; display:inline-flex; align-items:center; gap:4px;" title="Xóa quyền Quản Trị"><i class="fa-solid fa-trash"></i> Xóa Admin</button>` : `<span class="badge-verified" style="font-size:0.75rem; background:rgba(16,185,129,0.15); color:#10b981; border:1px solid #10b981;"><i class="fa-solid fa-shield"></i> Admin Duy Nhất</span>`}
          </div>
        `;
      }).join("");
    }
    window.renderAdminEmailsList = renderAdminEmailsList;


    // =========================================================================
    // CORE SYSTEM: TRANSACTION LOGS & HISTORY
    // =========================================================================
    function getTransactionHistory() {
      try {
        const stored = localStorage.getItem("mmo_transaction_history");
        if (stored) return JSON.parse(stored);
      } catch(e) {}
      return [];
    }
    window.getTransactionHistory = getTransactionHistory;

    function saveTransactionHistory(history) {
      try {
        localStorage.setItem("mmo_transaction_history", JSON.stringify(history));
      } catch(e) {}
    }
    window.saveTransactionHistory = saveTransactionHistory;

    function recordTransaction(userEmail, userName, type, amount, balanceAfter, note = "") {
      try {
        const history = getTransactionHistory();
        const txId = "TX" + Math.floor(10000000 + Math.random() * 90000000);
        const now = new Date();
        const timeStr = now.toLocaleDateString("vi-VN") + " " + now.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });

        const txObj = {
          id: txId,
          txId: txId,
          userEmail: (userEmail || "").trim(),
          userName: userName || userEmail,
          type: type,
          amount: amount,
          balanceAfter: balanceAfter,
          note: note,
          time: timeStr
        };

        history.unshift(txObj);
        saveTransactionHistory(history);
      } catch(e) {
        console.error("recordTransaction error:", e);
      }
    }
    window.recordTransaction = recordTransaction;

    // =========================================================================
    // CORE SYSTEM: ADMIN USERS TABLE & STATS RENDERING
    // =========================================================================
    function renderAdminUsersTable() {
      const tbody = document.getElementById("admUsersTableBody");
      if (!tbody) return;
      const search = (document.getElementById("admUserSearchInput")?.value || "").trim().toLowerCase();
      
      let users = getRegisteredUsers();

      if (search) {
        users = users.filter(u => (u.name || "").toLowerCase().includes(search) || (u.email || "").toLowerCase().includes(search));
      }

      // Update Header Stats
      const totalBal = users.reduce((sum, u) => sum + (u.balance || 0), 0);
      const countEl = document.getElementById("admUsersCountVal");
      const balEl = document.getElementById("admUsersTotalBalVal");
      if (countEl) countEl.innerText = users.length;
      if (balEl) balEl.innerText = formatVND(totalBal);

      const topStatUsersEl = document.getElementById("admStatUsers");
      if (topStatUsersEl) topStatUsersEl.innerText = users.length;

      if (users.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:24px; color:#64748b;">Không tìm thấy người dùng nào.</td></tr>';
        if (typeof renderPaginationUI === "function") renderPaginationUI("admUsersPagination", 1, 0, "changeAdmUsersPage");
        return;
      }

      // 10 Items per page pagination
      const page = (typeof paginationState !== "undefined" && paginationState.admUsers) ? paginationState.admUsers : 1;
      const totalPages = Math.ceil(users.length / ITEMS_PER_PAGE);
      const safePage = Math.max(1, Math.min(page, totalPages));
      if (typeof window.paginationState !== "undefined" && window.paginationState) paginationState.admUsers = safePage;

      const startIndex = (safePage - 1) * ITEMS_PER_PAGE;
      const pageUsers = users.slice(startIndex, startIndex + ITEMS_PER_PAGE);

      const rootEmail = (typeof ROOT_ADMIN_EMAIL !== "undefined" ? ROOT_ADMIN_EMAIL : "manhdongvtc@gmail.com").toLowerCase().trim();

      tbody.innerHTML = pageUsers.map(u => {
        const emailLower = (u.email || "").toLowerCase().trim();
        const isCurrent = currentUser && (currentUser.email || "").toLowerCase().trim() === emailLower;
        const displayBalance = isCurrent && currentUser.balance !== undefined ? Number(currentUser.balance) : (Number(u.balance) || 0);
        const isAdm = (emailLower === rootEmail || emailLower === "muabantaikhoanmmo@gmail.com" || (typeof isAdminUser === "function" && isAdminUser(u)) || u.role === "Quản Trị Viên");
        const roleHtml = isAdm ? '<span class="badge-trust" style="font-size:0.7rem; background:rgba(245,158,11,0.2); color:#f59e0b; border:1px solid rgba(245,158,11,0.4);">Quản Trị Viên</span>' : '<span class="badge-verified" style="font-size:0.7rem;">' + (u.role || "Thành Viên") + '</span>';
        
        const isLocked = !!u.isLocked;
        const statusHtml = isLocked 
          ? '<span style="color:#ef4444; font-size:0.75rem; font-weight:700; background:rgba(239,68,68,0.15); padding:3px 8px; border-radius:4px; border:1px solid rgba(239,68,68,0.3);"><i class="fa-solid fa-lock"></i> Đã Khóa</span>'
          : '<span style="color:#10b981; font-size:0.75rem; font-weight:700; background:rgba(16,185,129,0.15); padding:3px 8px; border-radius:4px; border:1px solid rgba(16,185,129,0.3);"><i class="fa-solid fa-circle-check"></i> Hoạt Động</span>';

        const isRoot = (emailLower === rootEmail);

        return '<tr>' +
          '<td>' +
            '<div onclick="openAdminUserDetailModal(\'' + escapeHtml(u.email) + '\')" style="display:flex; align-items:center; gap:10px; cursor:pointer; padding:4px 0;" title="👉 Bấm để xem Hồ Sơ & Lịch Sử Giao Dịch">' +
              '<img src="' + (u.avatar || 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png') + '" style="width:36px; height:36px; border-radius:50%; object-fit:cover; border:2px solid ' + (isAdm ? '#f59e0b' : '#10b981') + ';" />' +
              '<div>' +
                '<strong style="color:#fff; font-size:0.85rem; text-decoration:underline; text-underline-offset:2px;">' + escapeHtml(u.name || 'Thành Viên') + (isCurrent ? ' <span style="color:#10b981; font-size:0.75rem;">(Bạn)</span>' : '') + '</strong><br/>' +
                '<span style="font-size:0.75rem; color:#64748b;">' + escapeHtml(u.email) + '</span>' +
              '</div>' +
            '</div>' +
          '</td>' +
          '<td style="font-size:0.8rem; color:#cbd5e1;">' + escapeHtml(u.email) + '</td>' +
          '<td>' + roleHtml + '</td>' +
          '<td style="color:#10b981; font-weight:800; font-size:0.9rem;">' + formatVND(displayBalance) + '</td>' +
          '<td><span style="font-size:0.75rem; color:#94a3b8;">' + (u.created || '01/03/2026') + '</span></td>' +
          '<td>' +
            '<div style="display:flex; gap:6px; justify-content:center; flex-wrap:wrap;">' +
              '<button class="btn-action-copy" onclick="openAdminUserDetailModal(\'' + escapeHtml(u.email) + '\')" style="font-size:0.72rem; padding:4px 8px; background:rgba(56,189,248,0.15); border-color:rgba(56,189,248,0.3); color:#38bdf8; font-weight:700;" title="Xem Hồ Sơ & Lịch Sử">' +
                '<i class="fa-solid fa-eye"></i> Xem' +
              '</button>' +
              '<button class="btn-action-copy" onclick="openUserBalanceModal(\'' + escapeHtml(u.email) + '\')" style="font-size:0.72rem; padding:4px 8px; background:rgba(16,185,129,0.15); border-color:rgba(16,185,129,0.3); color:#10b981; font-weight:700;" title="Nạp / Trừ tiền">' +
                '<i class="fa-solid fa-plus-minus"></i> Nạp/Trừ' +
              '</button>' +
              (!isRoot ? 
                '<button class="btn-action-copy" onclick="toggleLockUser(\'' + escapeHtml(u.email) + '\')" style="font-size:0.72rem; padding:4px 8px; background:' + (isLocked ? 'rgba(16,185,129,0.15)' : 'rgba(245,158,11,0.15)') + '; border-color:' + (isLocked ? 'rgba(16,185,129,0.4)' : 'rgba(245,158,11,0.4)') + '; color:' + (isLocked ? '#10b981' : '#f59e0b') + ';" title="' + (isLocked ? 'Mở khóa' : 'Khóa tài khoản') + '">' +
                  '<i class="fa-solid ' + (isLocked ? 'fa-lock-open' : 'fa-lock') + '"></i> ' + (isLocked ? 'Mở' : 'Khóa') +
                '</button>' +
                '<button class="btn-action-copy" onclick="deleteUser(\'' + escapeHtml(u.email) + '\')" style="font-size:0.72rem; padding:4px 8px; background:rgba(239,68,68,0.15); border-color:rgba(239,68,68,0.3); color:#ef4444;" title="Xóa tài khoản">' +
                  '<i class="fa-solid fa-trash"></i>' +
                '</button>' : '') +
            '</div>' +
          '</td>' +
        '</tr>';
      }).join("");

      if (typeof renderPaginationUI === "function") {
        renderPaginationUI("admUsersPagination", safePage, users.length, "changeAdmUsersPage");
      }
    }
    window.renderAdminUsersTable = renderAdminUsersTable;

    // =========================================================================
    // CORE SYSTEM: ADMIN TRANSACTION HISTORY TABLE
    // =========================================================================
    function renderAdminTxTable() {
      const tbody = document.getElementById("admTxTableBody");
      if (!tbody) return;
      const history = getTransactionHistory();
      const txBadgeEl = document.getElementById("admTxCountBadge");
      if (txBadgeEl) txBadgeEl.innerText = history.length;

      if (history.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:24px; color:#64748b;">Chưa có lịch sử giao dịch nào được ghi lại.</td></tr>';
        if (typeof renderPaginationUI === "function") renderPaginationUI("admTxPagination", 1, 0, "changeAdmTxPage");
        return;
      }

      const page = (typeof paginationState !== "undefined" && paginationState.admTx) ? paginationState.admTx : 1;
      const totalPages = Math.ceil(history.length / ITEMS_PER_PAGE);
      const safePage = Math.max(1, Math.min(page, totalPages));
      if (typeof paginationState !== "undefined") paginationState.admTx = safePage;

      const startIndex = (safePage - 1) * ITEMS_PER_PAGE;
      const pageHistory = history.slice(startIndex, startIndex + ITEMS_PER_PAGE);

      tbody.innerHTML = pageHistory.map(tx => {
        const isPlus = tx.amount > 0;
        const amtHtml = isPlus ? '<span style="color:#10b981; font-weight:800;">+' + formatVND(tx.amount) + '</span>' : '<span style="color:#ef4444; font-weight:800;">' + formatVND(tx.amount) + '</span>';

        return '<tr>' +
          '<td style="font-family:monospace; font-weight:700; color:#38bdf8; font-size:0.78rem;">' + (tx.txId || tx.id) + '</td>' +
          '<td>' +
            '<strong style="color:#fff; font-size:0.82rem;">' + escapeHtml(tx.userName || 'User') + '</strong><br/>' +
            '<span style="font-size:0.72rem; color:#94a3b8; font-family:monospace;">' + escapeHtml(tx.userEmail) + '</span>' +
          '</td>' +
          '<td><span class="badge-verified" style="font-size:0.7rem;">' + escapeHtml(tx.type) + '</span></td>' +
          '<td>' + amtHtml + '</td>' +
          '<td style="font-family:monospace; color:#cbd5e1; font-size:0.8rem;">' + (typeof tx.balanceAfter === "number" ? formatVND(tx.balanceAfter) : tx.balanceAfter) + '</td>' +
          '<td style="font-size:0.75rem; color:#94a3b8;">' + tx.time + '</td>' +
          '<td style="font-size:0.78rem; color:#cbd5e1;">' + escapeHtml(tx.note || '') + '</td>' +
        '</tr>';
      }).join("");

      if (typeof renderPaginationUI === "function") {
        renderPaginationUI("admTxPagination", safePage, history.length, "changeAdmTxPage");
      }
    }
    window.renderAdminTxTable = renderAdminTxTable;

    // =========================================================================
    // CORE SYSTEM: ADMIN DASHBOARD & STATS
    // =========================================================================
    let admProductStockFilter = "ALL";
    function setAdmProductFilter(filterType) {
      admProductStockFilter = filterType;
      const btns = {
        ALL: "admProdFilterAll",
        IN_STOCK: "admProdFilterInStock",
        OUT_OF_STOCK: "admProdFilterOutOfStock",
        LOW_STOCK: "admProdFilterLowStock"
      };
      Object.keys(btns).forEach(function(k) {
        const btn = document.getElementById(btns[k]);
        if (btn) {
          if (k === filterType) {
            btn.style.background = (k === "OUT_OF_STOCK") ? "rgba(239,68,68,0.25)" : (k === "IN_STOCK") ? "rgba(16,185,129,0.25)" : (k === "LOW_STOCK") ? "rgba(245,158,11,0.25)" : "rgba(59,130,246,0.25)";
            btn.style.color = (k === "OUT_OF_STOCK") ? "#f87171" : (k === "IN_STOCK") ? "#34d399" : (k === "LOW_STOCK") ? "#fbbf24" : "#60a5fa";
          } else {
            btn.style.background = "transparent";
            btn.style.color = "#94a3b8";
          }
        }
      });
      if (typeof paginationState !== "undefined") paginationState.admProd = 1;
      renderAdminDashboard();
    }
    window.setAdmProductFilter = setAdmProductFilter;

    function renderAdminDashboard() {
      try {
        const tbody = document.querySelector("#admProductsTable tbody");
        if (tbody) {
          let prods = (MOCK_DATA && MOCK_DATA.products) ? [...MOCK_DATA.products] : [];
          
          // Áp dụng bộ lọc tồn kho thông minh
          if (admProductStockFilter === "IN_STOCK") {
            prods = prods.filter(function(p) {
              const s = (typeof getVariantStockCount === "function") ? getVariantStockCount(p, null) : getProductStockCount(p);
              return s > 0;
            });
          } else if (admProductStockFilter === "OUT_OF_STOCK") {
            prods = prods.filter(function(p) {
              const s = (typeof getVariantStockCount === "function") ? getVariantStockCount(p, null) : getProductStockCount(p);
              return s === 0;
            });
          } else if (admProductStockFilter === "LOW_STOCK") {
            prods = prods.filter(function(p) {
              const s = (typeof getVariantStockCount === "function") ? getVariantStockCount(p, null) : getProductStockCount(p);
              return s > 0 && s < 5;
            });
          }

          const ADM_PRODS_PER_PAGE = 10;
          const page = (typeof paginationState !== "undefined" && paginationState.admProd) ? paginationState.admProd : 1;
          const totalPages = Math.ceil(prods.length / ADM_PRODS_PER_PAGE);
          const safePage = Math.max(1, Math.min(page, totalPages || 1));
          if (typeof paginationState !== "undefined") paginationState.admProd = safePage;

          const startIndex = (safePage - 1) * ADM_PRODS_PER_PAGE;
          const pageProds = prods.slice(startIndex, startIndex + ADM_PRODS_PER_PAGE);

          if (prods.length === 0) {
            tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:24px; color:#64748b;">Chưa có sản phẩm nào. Hãy bấm "Thêm Sản Phẩm" để tạo mới.</td></tr>';
          } else {
            tbody.innerHTML = pageProds.map(function(p) {
              const vCount = (p.variants && p.variants.length) ? p.variants.length : 1;
              return '<tr>' +
                '<td>' + p.id + '</td>' +
                '<td><img src="' + p.image + '" style="width:36px; height:36px; border-radius:4px; object-fit:cover;" /></td>' +
                '<td><a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" style="color:#ffffff; text-decoration:none; font-weight:700; display:inline-flex; align-items:center; gap:6px;" onmouseover="this.style.color=\'#10b981\'" onmouseout="this.style.color=\'#ffffff\'" title="Mở xem chi tiết sản phẩm trong tab mới"><strong>' + escapeHtml(p.name) + '</strong> <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:0.75rem; color:#38bdf8;"></i></a><br/>' +
                  (function() {
                    const apiMap = (typeof getApiProductMapping === "function") ? getApiProductMapping(p.id) : null;
                    const isApi = !!(apiMap && apiMap.enabled && apiMap.sourceProdId);
                    if (isApi) {
                      return '<span style="font-size:0.68rem; background:rgba(6,182,212,0.15); color:#06b6d4; border:1px solid rgba(6,182,212,0.3); padding:1px 6px; border-radius:4px; font-weight:700; display:inline-flex; align-items:center; gap:3px; margin-right:6px;"><i class="fa-solid fa-bolt"></i> API: ' + (apiMap.provider || 'Nguồn') + ' [#' + (apiMap.sourceProdId) + ']</span>';
                    }
                    return '<span style="font-size:0.68rem; background:rgba(16,185,129,0.15); color:#10b981; border:1px solid rgba(16,185,129,0.3); padding:1px 6px; border-radius:4px; font-weight:700; display:inline-flex; align-items:center; gap:3px; margin-right:6px;"><i class="fa-solid fa-box"></i> Kho Nội Bộ</span>';
                  })() +
                  '<span style="font-size:0.75rem; color:#38bdf8;">' + vCount + ' Biến thể</span></td>' +
                '<td>' + escapeHtml(p.category) + '</td>' +
                '<td style="color:#10b981; font-weight:700;">' + formatVND(p.price) + '</td>' +
                '<td>' + (function() {
                  const stk = typeof getProductStockCount === "function" ? getProductStockCount(p) : (p.stock || 0);
                  if (stk === 0) return '<span style="color:#ef4444; font-weight:800; background:rgba(239,68,68,0.15); padding:3px 8px; border-radius:4px; border:1px solid rgba(239,68,68,0.3); font-size:0.75rem;"><i class="fa-solid fa-circle-xmark"></i> 0 (Hết hàng)</span>';
                  if (stk < 5) return '<span style="color:#f59e0b; font-weight:800; background:rgba(245,158,11,0.15); padding:3px 8px; border-radius:4px; border:1px solid rgba(245,158,11,0.3); font-size:0.75rem;"><i class="fa-solid fa-triangle-exclamation"></i> ' + stk + ' (Sắp hết)</span>';
                  return '<span class="badge-verified" style="font-weight:700;">' + stk + ' acc</span>';
                })() + '</td>' +
                '<td>' +
                  '<div style="display:flex; gap:6px;">' +
                    '<button class="btn-copy-small" onclick="openEditProductModal(\'' + p.id + '\')" title="Sửa"><i class="fa-regular fa-pen-to-square"></i></button>' +
                    '<button class="btn-copy-small" onclick="quickOpenStockForProduct(\'' + p.id + '\')" title="Nạp Kho"><i class="fa-solid fa-warehouse"></i></button>' +
                    '<button class="btn-copy-small" onclick="deleteProduct(\'' + p.id + '\')" title="Xóa tài khoản / sản phẩm" style="color:#ef4444; border-color:rgba(239,68,68,0.4);"><i class="fa-solid fa-trash"></i></button>' +
                  '</div>' +
                '</td>' +
              '</tr>';
            }).join("");
          }

          if (typeof renderPaginationUI === "function") {
            renderPaginationUI("admProdPagination", safePage, prods.length, "changeAdmProdPage", ADM_PRODS_PER_PAGE);
          }
        }

        const statRev = document.getElementById("admStatRev");
        const statUsers = document.getElementById("admStatUsers");
        const statStock = document.getElementById("admStatStock");
        const statPaid = document.getElementById("admStatPaid");

        const users = getRegisteredUsers();
        if (statRev) statRev.innerText = formatVND(18500000);
        if (statUsers) statUsers.innerText = users.length;
        if (statStock) statStock.innerText = "1,850";
        if (statPaid) statPaid.innerText = "284";

        if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      } catch(e) {
        console.error("renderAdminDashboard error:", e);
      }
    }
    window.renderAdminDashboard = renderAdminDashboard;

    // =========================================================================
    // TRANG TỔNG QUAN HỆ THỐNG (SYSTEM OVERVIEW DASHBOARD)
    // =========================================================================
    async function syncSystemOverviewWithCloud() {
      if (typeof showToast === "function") showToast("⏳ Đang đồng bộ dữ liệu từ Google Sheets Cloud...", "info");
      try {
        if (typeof fetchCloudUsers === "function") {
          await fetchCloudUsers(false);
        }
        if (typeof fetchAdminOrdersFromCloud === "function") {
          await fetchAdminOrdersFromCloud();
        }
        if (typeof renderSystemOverview === "function") {
          renderSystemOverview();
        }
        if (typeof showToast === "function") showToast("✅ Đã cập nhật xong dữ liệu thực tế từ Cloud!", "success");
      } catch(e) {
        console.error("syncSystemOverviewWithCloud error:", e);
        if (typeof renderSystemOverview === "function") renderSystemOverview();
      }
    }
    window.syncSystemOverviewWithCloud = syncSystemOverviewWithCloud;

    function renderSystemOverview() {
      try {
        // 1. Dữ liệu nguồn thực tế 100% từ hệ thống (Local Storage & Cloud)
        const products = (typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        const activeProducts = products.filter(function(p) { return !p.isDeleted; });
        const users = (typeof getRegisteredUsers === "function") ? getRegisteredUsers() : [];
        const allOrders = (typeof getAllOrders === "function") ? getAllOrders() : [];
        const withdraws = (typeof getWithdrawRequests === "function") ? getWithdrawRequests() : [];
        const txHistory = (typeof getTransactionHistory === "function") ? getTransactionHistory() : [];
        let affOrders = [];
        try {
          affOrders = JSON.parse(localStorage.getItem("mmo_affiliate_orders") || "[]");
        } catch(e) {}

        // 2. Tính Tổng Doanh Thu (GMV) và Lợi Nhuận Gộp Thực Tế
        let totalGMV = 0;
        let successfulOrdersCount = 0;
        let totalGrossProfit = 0;
        let totalSourceCost = 0;

        allOrders.forEach(function(o) {
          const st = (o.status || "").toUpperCase();
          const em = String(o.email || o.userEmail || o.buyer || "").toLowerCase().trim();
          const oId = String(o.orderId || o.id || "").toUpperCase();
          const isDemo = oId === "MMO888999" || oId.includes("SAMPLE") || oId.includes("DEMO") || oId.includes("TEST") || 
                         !em || !em.includes("@") || em.includes("sample") || em.includes("demo") || em === "khachhang@gmail.com" || em.includes("test@") || em.includes("khach@");
          if (isDemo) return;

          if (st !== "CANCELLED" && st !== "REFUNDED" && st !== "ĐÃ HOÀN TIỀN" && st !== "HUỶ" && st !== "ĐÃ HỦY") {
            const amt = Number(o.total || o.totalPrice || o.totalAmount || o.amount || 0);
            if (amt > 0) {
              totalGMV += amt;
              successfulOrdersCount++;

              // Tính giá vốn nguồn thực tế nếu là sản phẩm dropship qua API nguồn (sellmmo, nguyenlieummo, selltainguyenmmo...)
              const qty = Number(o.quantity || o.qty || 1);
              let unitCost = 0;
              if (typeof o.cost === "number" && o.cost > 0) {
                unitCost = o.cost / qty;
              } else if (typeof o.sourceCost === "number" && o.sourceCost > 0) {
                unitCost = o.sourceCost / qty;
              } else {
                const pId = o.productId || o.prodId;
                const apiMap = (typeof getApiProductMapping === "function" && pId) ? getApiProductMapping(pId) : null;
                if (apiMap && apiMap.enabled && apiMap.sourcePrice) {
                  unitCost = Number(apiMap.sourcePrice) || 0;
                }
              }
              const orderCost = unitCost * qty;
              totalSourceCost += orderCost;
              totalGrossProfit += Math.max(0, amt - orderCost);
            }
          }
        });

        // Nếu chưa có đơn hàng lưu trong allOrders, lấy từ lịch sử thanh toán mua hàng thực tế
        if (totalGMV === 0 && txHistory.length > 0) {
          txHistory.forEach(function(tx) {
            const note = ((tx.note || "") + " " + (tx.type || "")).toLowerCase();
            if (note.includes("thanh toán") || note.includes("mua hàng") || note.includes("mua sp") || note.includes("mua ")) {
              const amt = Math.abs(Number(tx.amount) || 0);
              if (amt > 0) {
                totalGMV += amt;
                totalGrossProfit += amt;
                successfulOrdersCount++;
              }
            }
          });
        }

        // 3. Tính Chi Trả Affiliate Thực Tế 100% (Không dùng số liệu mẫu demo)
        let totalAffiliate = 0;
        if (Array.isArray(affOrders)) {
          affOrders.forEach(function(ao) {
            totalAffiliate += Math.abs(Number(ao.commissionAmount) || 0);
          });
        }
        txHistory.forEach(function(tx) {
          const typeStr = ((tx.type || "") + " " + (tx.note || "")).toLowerCase();
          if (typeStr.includes("hoa hồng") || typeStr.includes("affiliate") || typeStr.includes("giới thiệu")) {
            const amt = Math.abs(Number(tx.amount) || 0);
            if (affOrders.length === 0 && amt > 0) {
              totalAffiliate += amt;
            }
          }
        });

        // 4. Tính Ví Tổng Thực Tế (Tổng tiền người dùng nạp vào sàn)
        let totalDepositsFromTx = 0;
        txHistory.forEach(function(tx) {
          const t = ((tx.type || "") + " " + (tx.note || "")).toLowerCase();
          if (t.includes("nạp tiền") || t.includes("sepay") || t.includes("deposit") || t.includes("ngân hàng") || t.includes("cộng tiền") || t.includes("nạp quỹ")) {
            totalDepositsFromTx += Math.abs(Number(tx.amount) || 0);
          }
        });
        // Đảm bảo đồng bộ số dư mới nhất của currentUser (nếu đang đăng nhập) vào danh sách users
        try {
          const curU = (typeof currentUser !== "undefined" && currentUser) ? currentUser : JSON.parse(localStorage.getItem("mmo_user") || "null");
          if (curU && curU.email) {
            const uIdx = users.findIndex(function(u) { return (u.email || "").toLowerCase().trim() === curU.email.toLowerCase().trim(); });
            if (uIdx !== -1 && curU.balance !== undefined && curU.balance !== null) {
              users[uIdx].balance = Number(curU.balance) || 0;
            }
          }
        } catch(eSyncU) {}

        // Số dư thực tế khả dụng của tất cả các thành viên (tự động giảm khi khách mua hàng hoặc chi tiêu dịch vụ)
        const totalUserBalance = users.reduce(function(sum, u) { return sum + (Number(u.balance) || 0); }, 0);
        
        // Tiền thực nạp vào sàn = Tổng các giao dịch nạp tiền thành công (hoặc số dư còn lại + số tiền đã chi tiêu nếu không có log nạp)
        let totalDeposit = totalDepositsFromTx;
        if (totalDeposit < (totalUserBalance + totalGMV)) {
          totalDeposit = totalUserBalance + totalGMV;
        }

        // 5. Tính Lợi Nhuận Ròng Thực Tế 100% (Net Profit)
        // Lợi nhuận ròng = Tổng lợi nhuận gộp (Doanh thu - Giá vốn nguồn API) - Chi trả Affiliate thực tế
        const netProfit = Math.max(0, totalGrossProfit - totalAffiliate);

        // 6. Tính Tồn Kho & Sản Phẩm Đang Bán / Đã Bán THỰC TẾ 100% (LOẠI BỎ TOÀN BỘ ĐƠN ẢO, BUFF ẢO & KHO ẢO)
        let totalStockAccounts = 0;
        activeProducts.forEach(function(p) {
          // Tính số lượng tài khoản (acc) thực tế có trong kho nội bộ (do Admin nạp)
          let realProdStock = 0;
          if (Array.isArray(p.variants) && p.variants.length > 0) {
            p.variants.forEach(function(v) {
              if (Array.isArray(v.accounts)) realProdStock += v.accounts.length;
            });
          } else if (Array.isArray(p.accounts)) {
            realProdStock += p.accounts.length;
          }

          if (typeof MMO_WAREHOUSE !== "undefined" && typeof MMO_WAREHOUSE.getAvailable === "function") {
            const whAccs = MMO_WAREHOUSE.getAvailable(p.id, "ALL");
            if (Array.isArray(whAccs) && whAccs.length > realProdStock) {
              realProdStock = whAccs.length;
            }
          }

          // Nếu là sản phẩm liên kết nguồn API có tồn kho thực (loại bỏ hoàn toàn số ảo >= 999999)
          if (realProdStock === 0 && typeof getApiProductMapping === "function") {
            const apiMap = getApiProductMapping(p);
            if (apiMap && apiMap.enabled && apiMap.sourceProdId) {
              const sStock = Number(apiMap.sourceStock) || 0;
              if (sStock > 0 && sStock < 999999) {
                realProdStock = sStock;
              }
            }
          }

          // Kho tài khoản chỉ tính số lượng tài khoản (acc) thực tế có thể giao dịch

          totalStockAccounts += realProdStock;
        });

        // Tính chính xác đơn hàng đã bán thực tế từ khách hàng (Loại bỏ hoàn toàn đơn ảo, buff ảo, đơn mẫu demo, đơn huỷ)
        let finalSoldOrders = 0;
        let finalSoldAccounts = 0;

        allOrders.forEach(function(o) {
          const st = String(o.status || "").toLowerCase().trim();
          const em = String(o.email || o.userEmail || o.buyer || "").toLowerCase().trim();
          const oId = String(o.orderId || o.id || "").toUpperCase();

          // Lọc bỏ đơn ảo / demo / sample
          const isDemo = oId === "MMO888999" || oId.includes("SAMPLE") || oId.includes("DEMO") || oId.includes("TEST") || 
                         !em || !em.includes("@") || em.includes("sample") || em.includes("demo") || em === "khachhang@gmail.com" || em.includes("test@") || em.includes("khach@");
          const isCancelled = st.includes("huỷ") || st.includes("hủy") || st === "cancelled";

          if (!isDemo && !isCancelled) {
            const qty = Number(o.quantity || o.qty || 1);
            finalSoldOrders++;
            finalSoldAccounts += qty;
          }
        });

        // 7. Yêu Cầu Rút Tiền
        const pendingWithdraws = withdraws.filter(function(w) {
          const st = (w.status || "").toLowerCase();
          return st.includes("chờ") || st === "pending";
        });
        const completedWithdraws = withdraws.filter(function(w) {
          const st = (w.status || "").toLowerCase();
          return st.includes("duyệt") || st.includes("thành công") || st === "completed";
        });
        const completedWithdrawSum = completedWithdraws.reduce(function(sum, w) { return sum + (Number(w.amount) || 0); }, 0);

        // 8. Đơn Hàng Cần Xử Lý (Bao gồm CẢ Khiếu nại bảo hành VÀ Đơn đặt trước chờ xử lý - Hình 2)
        const rawPreOrders = (typeof getPreOrders === "function") ? getPreOrders(true) : [];
        const waitingPreOrders = rawPreOrders.filter(function(po) {
          const st = (po.status || "").toUpperCase();
          const stTxt = String(po.statusText || "").toLowerCase();
          const isCancelled = st === "CANCELLED" || st === "REFUNDED" || stTxt.includes("hủy") || stTxt.includes("hoàn tiền") || Boolean(po.isCancelled) || Boolean(po.isRefunded);
          if (isCancelled || st === "COMPLETED") return false;
          return st === "WAITING_CONFIRM" || st === "PROCESSING" || stTxt.includes("chờ") || stTxt.includes("gom hàng");
        });

        const pendingWarrantyOrders = allOrders.filter(function(o) {
          const st = (o.status || "").toLowerCase().trim();
          if (!st) return false;

          // Bỏ qua các đơn đã hoàn tất đổi trả, đã hoàn tiền hoặc đã hủy
          if (st.includes("đã đổi trả") || st.includes("đã hoàn tiền") || st.includes("đã hủy") || st.includes("huỷ")) {
            return false;
          }

          // Bỏ qua đơn đặt trước vì đã gom vào waitingPreOrders
          const oId = String(o.id || o.orderCode || o.orderId || "");
          if (o.type === "PRE_ORDER" || oId.startsWith("PRE")) {
            return false;
          }

          // Bỏ qua các đơn đã giao thành công / hoàn thành bình thường
          const isDeliveredOrDone = st === "hoàn thành" || st === "completed" || st === "đã giao" || st === "paid" || st === "success" || st.includes("giao thành công") || st === "tự động";
          if (isDeliveredOrDone) {
            return false;
          }

          // Chỉ lấy các đơn có trạng thái khiếu nại, báo lỗi, bảo hành, chờ đổi trả hoặc cần xử lý
          return st.includes("khiếu nại") || st.includes("báo lỗi") || st.includes("bảo hành") || st.includes("chờ đổi trả") || st.includes("cần bảo hành") || st.includes("chờ xử lý") || st.includes("đổi trả");
        });

        // Hợp nhất danh sách đơn cần xử lý: Đơn đặt trước chờ xử lý + Đơn khiếu nại
        const pendingOrders = [
          ...waitingPreOrders.map(function(po) {
            return {
              ...po,
              isPreOrderTask: true,
              taskTypeBadge: '<span style="background:rgba(245,158,11,0.15); color:#f59e0b; border:1px solid rgba(245,158,11,0.3); font-weight:800; padding:2px 7px; border-radius:4px; font-size:0.72rem; display:inline-flex; align-items:center; gap:4px;"><i class=\"fa-solid fa-hourglass-half\"></i> ĐẶT TRƯỚC</span>'
            };
          }),
          ...pendingWarrantyOrders.map(function(wo) {
            return {
              ...wo,
              isPreOrderTask: false,
              taskTypeBadge: '<span style="background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); font-weight:800; padding:2px 7px; border-radius:4px; font-size:0.72rem; display:inline-flex; align-items:center; gap:4px;"><i class=\"fa-solid fa-shield-halved\"></i> KHIẾU NẠI</span>'
            };
          })
        ];

        // Cập nhật lên DOM
        const elNetProfit = document.getElementById("ovwNetProfit");
        const elNetProfitAffSub = document.getElementById("ovwNetProfitAffSub");
        const elGrossRevenue = document.getElementById("ovwGrossRevenue");
        const elTotalDeposit = document.getElementById("ovwTotalDeposit");
        const elTotalDepositSub = document.getElementById("ovwTotalDepositSub");
        const elMemberBalSub = document.getElementById("ovwMemberBalSub");
        const elAffiliatePayout = document.getElementById("ovwAffiliatePayout");

        if (elNetProfit) elNetProfit.innerText = (typeof formatVND === "function") ? formatVND(netProfit) : (netProfit.toLocaleString("vi-VN") + " đ");
        if (elNetProfitAffSub) elNetProfitAffSub.innerText = (typeof formatVND === "function") ? formatVND(totalAffiliate) : (totalAffiliate.toLocaleString("vi-VN") + " đ");
        if (elGrossRevenue) elGrossRevenue.innerText = (typeof formatVND === "function") ? formatVND(totalGMV) : (totalGMV.toLocaleString("vi-VN") + " đ");
        if (elTotalDeposit) elTotalDeposit.innerText = (typeof formatVND === "function") ? formatVND(totalUserBalance) : (totalUserBalance.toLocaleString("vi-VN") + " đ");
        if (elTotalDepositSub) elTotalDepositSub.innerText = (typeof formatVND === "function") ? formatVND(totalDeposit) : (totalDeposit.toLocaleString("vi-VN") + " đ");
        if (elMemberBalSub) elMemberBalSub.innerText = (typeof formatVND === "function") ? formatVND(totalGMV) : (totalGMV.toLocaleString("vi-VN") + " đ");
        if (elAffiliatePayout) elAffiliatePayout.innerText = (typeof formatVND === "function") ? formatVND(totalAffiliate) : (totalAffiliate.toLocaleString("vi-VN") + " đ");

        // Hàng thẻ hoạt động bổ sung
        const elTotalProducts = document.getElementById("ovwTotalProducts");
        const elTotalStockAccounts = document.getElementById("ovwTotalStockAccounts");
        const elTotalSoldOrders = document.getElementById("ovwTotalSoldOrders");
        const elTotalSoldAccounts = document.getElementById("ovwTotalSoldAccounts");
        const elPendingWithdrawCount = document.getElementById("ovwPendingWithdrawCount");
        const elCompletedWithdrawSum = document.getElementById("ovwCompletedWithdrawSum");
        const elPendingOrdersCount = document.getElementById("ovwPendingOrdersCount");
        const elTotalUsers = document.getElementById("ovwTotalUsers");
        const elTotalUserBalance = document.getElementById("ovwTotalUserBalance");

        if (elTotalProducts) elTotalProducts.innerText = activeProducts.length;
        if (elTotalStockAccounts) elTotalStockAccounts.innerText = totalStockAccounts.toLocaleString("vi-VN");
        if (elTotalSoldOrders) elTotalSoldOrders.innerText = finalSoldOrders.toLocaleString("vi-VN") + " đơn";
        if (elTotalSoldAccounts) elTotalSoldAccounts.innerText = finalSoldAccounts.toLocaleString("vi-VN");
        if (elPendingWithdrawCount) {
          elPendingWithdrawCount.innerText = pendingWithdraws.length + " chờ duyệt";
          elPendingWithdrawCount.style.color = pendingWithdraws.length > 0 ? "#f59e0b" : "#10b981";
        }
        if (elCompletedWithdrawSum) elCompletedWithdrawSum.innerText = (typeof formatVND === "function") ? formatVND(completedWithdrawSum) : (completedWithdrawSum.toLocaleString("vi-VN") + " đ");
        if (elPendingOrdersCount) {
          elPendingOrdersCount.innerText = pendingOrders.length + " đơn cần xử lý";
          elPendingOrdersCount.style.color = pendingOrders.length > 0 ? "#ef4444" : "#10b981";
        }
        const elPendingOrdersSub = document.getElementById("ovwPendingOrdersSub");
        if (elPendingOrdersSub) {
          elPendingOrdersSub.innerHTML = 'Khiếu nại: <b>' + pendingWarrantyOrders.length + '</b> | Đặt trước: <b>' + waitingPreOrders.length + '</b>';
        }
        if (elTotalUsers) elTotalUsers.innerText = users.length;
        if (elTotalUserBalance) elTotalUserBalance.innerText = (typeof formatVND === "function") ? formatVND(totalUserBalance) : (totalUserBalance.toLocaleString("vi-VN") + " đ");

        // Huy hiệu badge ở 2 bảng tác vụ
        const elBadgeOrders = document.getElementById("ovwBadgePendingOrders");
        const elBadgeWithdraw = document.getElementById("ovwBadgePendingWithdraw");
        if (elBadgeOrders) elBadgeOrders.innerText = pendingOrders.length;
        if (elBadgeWithdraw) elBadgeWithdraw.innerText = pendingWithdraws.length;

        // Render Panel 1: Đơn hàng cần xử lý (Phân trang 10 đơn / trang)
        const ordersBox = document.getElementById("ovwPendingOrdersContainer");
        if (ordersBox) {
          if (pendingOrders.length === 0) {
            ordersBox.innerHTML = '<div style="background:rgba(16,185,129,0.06); border:1px dashed rgba(16,185,129,0.25); border-radius:8px; padding:20px; text-align:center; color:#10b981;">' +
              '<i class="fa-solid fa-circle-check" style="font-size:1.8rem; margin-bottom:8px; display:block;"></i>' +
              '<div style="font-weight:700; font-size:0.9rem;">Hệ thống không có đơn hàng nào đang chờ xử lý!</div>' +
              '<div style="font-size:0.75rem; color:#94a3b8; margin-top:4px;">Tất cả đơn hàng của khách đều đã được tự động cấp tài khoản và vận hành ổn định.</div>' +
            '</div>';
          } else {
            const pageSize = 10;
            const totalPages = Math.ceil(pendingOrders.length / pageSize) || 1;
            if (!window._ovwPendingOrdersPage || window._ovwPendingOrdersPage < 1) window._ovwPendingOrdersPage = 1;
            if (window._ovwPendingOrdersPage > totalPages) window._ovwPendingOrdersPage = totalPages;
            const curPage = window._ovwPendingOrdersPage;
            const startIdx = (curPage - 1) * pageSize;
            const pageOrders = pendingOrders.slice(startIdx, startIdx + pageSize);

            let tableHtml = '<div style="overflow-x:auto;"><table class="admin-table" style="width:100%; font-size:0.8rem;">' +
              '<thead><tr><th>Loại / Mã Đơn</th><th>Khách Hàng</th><th>Sản Phẩm</th><th>Số Tiền</th><th>Trạng Thái</th><th style="text-align:right;">Thao Tác</th></tr></thead><tbody>';
            pageOrders.forEach(function(item) {
              const orderId = item.orderCode || item.orderId || item.id || "DH";
              const userStr = item.buyerUsername || item.buyerEmail || item.userEmail || item.buyer || item.customer || "Khách hàng";
              const prodName = item.productName || item.prodName || item.name || "Sản phẩm";
              const amtStr = (typeof formatVND === "function") ? formatVND(item.total || item.totalPrice || item.price || 0) : ((item.total || 0) + " đ");
              const badge = item.taskTypeBadge || '<span style="background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); font-size:0.7rem; font-weight:700; padding:2px 6px; border-radius:4px;">Khiếu nại</span>';

              let actionBtns = '';
              if (item.isPreOrderTask) {
                actionBtns = '<div style="display:inline-flex; gap:4px; justify-content:flex-end;">' +
                  (item.status === 'WAITING_CONFIRM' ? '<button type="button" onclick="adminConfirmPreOrder(\'' + escapeHtml(orderId) + '\')" class="btn-action-copy" style="padding:3px 7px; font-size:0.72rem; background:#38bdf8; color:#0b111e; font-weight:700; border:none; border-radius:4px; cursor:pointer;" title="Duyệt đơn"><i class="fa-solid fa-check"></i> Duyệt</button>' : '') +
                  '<button type="button" onclick="openAdminFulfillModal(\'' + escapeHtml(orderId) + '\')" class="btn-action-copy" style="padding:3px 7px; font-size:0.72rem; background:#10b981; color:#0b111e; font-weight:700; border:none; border-radius:4px; cursor:pointer;" title="Giao hàng cho khách"><i class="fa-solid fa-key"></i> Giao</button>' +
                  '<button type="button" onclick="openPreOrderDetailView(\'' + escapeHtml(orderId) + '\')" class="btn-action-copy" style="padding:3px 7px; font-size:0.72rem; background:#1e293b; color:#cbd5e1; border:1px solid #334155; border-radius:4px; cursor:pointer;" title="Xem chi tiết đơn"><i class="fa-solid fa-eye"></i></button>' +
                '</div>';
              } else {
                actionBtns = '<button class="btn-copy-small" onclick=\'openAdminOrderResolveModal("' + escapeHtml(orderId) + '")\' style="background:#0284c7; color:#fff; padding:3px 8px; font-size:0.72rem;" title="Mở đổi trả 1-đổi-1 hoặc hoàn tiền">' +
                  '<i class="fa-solid fa-arrows-rotate"></i> Đổi Trả' +
                '</button>';
              }

              tableHtml += '<tr>' +
                '<td>' + badge + '<br/><strong style="color:#38bdf8; font-size:0.78rem;">#' + escapeHtml(orderId) + '</strong></td>' +
                '<td><b>' + escapeHtml(userStr) + '</b></td>' +
                '<td><div style="font-weight:600; color:#fff;">' + escapeHtml(prodName) + '</div>' + (item.qty ? ('<span style="font-size:0.7rem; color:#94a3b8;">SL: ' + item.qty + '</span>') : '') + '</td>' +
                '<td style="color:#10b981; font-weight:700;">' + amtStr + '</td>' +
                '<td><span style="background:rgba(245,158,11,0.15); color:#f59e0b; border:1px solid rgba(245,158,11,0.3); font-size:0.7rem; font-weight:700; padding:2px 6px; border-radius:4px;">' + escapeHtml(item.statusText || item.status || "Chờ xử lý") + '</span></td>' +
                '<td style="text-align:right;">' + actionBtns + '</td>' +
              '</tr>';
            });
            tableHtml += '</tbody></table></div>';
            tableHtml += buildOvwPaginationHtml(curPage, pendingOrders.length, pageSize, "changeOvwPendingOrdersPage");
            ordersBox.innerHTML = tableHtml;
          }
        }

        // Render Panel 2: Yêu cầu rút tiền chờ duyệt (Phân trang 10 đơn / trang)
        const withdrawBox = document.getElementById("ovwPendingWithdrawContainer");
        if (withdrawBox) {
          if (pendingWithdraws.length === 0) {
            withdrawBox.innerHTML = '<div style="background:rgba(16,185,129,0.06); border:1px dashed rgba(16,185,129,0.25); border-radius:8px; padding:20px; text-align:center; color:#10b981;">' +
              '<i class="fa-solid fa-circle-check" style="font-size:1.8rem; margin-bottom:8px; display:block;"></i>' +
              '<div style="font-weight:700; font-size:0.9rem;">Không có yêu cầu nạp hoặc rút tiền nào tồn đọng!</div>' +
              '<div style="font-size:0.75rem; color:#94a3b8; margin-top:4px;">Các lệnh rút tiền của thành viên đã được phê duyệt và giải ngân đầy đủ.</div>' +
            '</div>';
          } else {
            const wPageSize = 10;
            const wTotalPages = Math.ceil(pendingWithdraws.length / wPageSize) || 1;
            if (!window._ovwPendingWithdrawPage || window._ovwPendingWithdrawPage < 1) window._ovwPendingWithdrawPage = 1;
            if (window._ovwPendingWithdrawPage > wTotalPages) window._ovwPendingWithdrawPage = wTotalPages;
            const curWPage = window._ovwPendingWithdrawPage;
            const wStartIdx = (curWPage - 1) * wPageSize;
            const pageWithdraws = pendingWithdraws.slice(wStartIdx, wStartIdx + wPageSize);

            let wTableHtml = '<div style="overflow-x:auto;"><table class="admin-table" style="width:100%; font-size:0.8rem;">' +
              '<thead><tr><th>Mã GD</th><th>Thành Viên</th><th>Số Tiền</th><th>Ngân Hàng</th><th style="text-align:right;">Hành Động</th></tr></thead><tbody>';
            pageWithdraws.forEach(function(item) {
              const id = item.id || "W";
              const userStr = item.userName || item.userEmail || "Thành viên";
              const amtStr = (typeof formatVND === "function") ? formatVND(item.amount || 0) : (item.amount || 0) + " đ";
              const bankStr = (item.bankName || "") + " - " + (item.bankNumber || "");
              wTableHtml += '<tr>' +
                '<td><strong style="color:#f59e0b;">' + escapeHtml(id) + '</strong></td>' +
                '<td>' + escapeHtml(userStr) + '</td>' +
                '<td style="color:#ef4444; font-weight:700;">' + amtStr + '</td>' +
                '<td style="font-size:0.75rem;">' + escapeHtml(bankStr) + '</td>' +
                '<td style="text-align:right;">' +
                  '<button class="btn-copy-small" onclick=\'approveWithdraw("' + escapeHtml(id) + '")\' style="background:#10b981; color:#fff; padding:3px 8px; font-size:0.72rem; margin-right:4px;" title="Duyệt rút tiền">' +
                    '<i class="fa-solid fa-check"></i> Duyệt' +
                  '</button>' +
                  '<button class="btn-copy-small" onclick=\'rejectWithdraw("' + escapeHtml(id) + '")\' style="background:#ef4444; color:#fff; padding:3px 8px; font-size:0.72rem;" title="Từ chối lệnh">' +
                    '<i class="fa-solid fa-xmark"></i>' +
                  '</button>' +
                '</td>' +
              '</tr>';
            });
            wTableHtml += '</tbody></table></div>';
            wTableHtml += buildOvwPaginationHtml(curWPage, pendingWithdraws.length, wPageSize, "changeOvwPendingWithdrawPage");
            withdrawBox.innerHTML = wTableHtml;
          }
        }

        // Render Bảng Phân Bổ Tồn Kho Theo Danh Mục
        const catTbody = document.getElementById("ovwCategoryStockTableBody");
        if (catTbody) {
          const cats = (typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.categories)) ? MOCK_DATA.categories : ["Gmail", "TikTok", "Facebook", "Telegram", "Proxy"];
          let catRows = "";
          cats.forEach(function(cat) {
            const prodsInCat = activeProducts.filter(function(p) { return (p.category || "").toLowerCase() === cat.toLowerCase(); });
            let catStock = 0;
            prodsInCat.forEach(function(p) {
              catStock += (typeof getVariantStockCount === "function") ? getVariantStockCount(p) : (Number(p.stock) || 0);
            });
            let statusBadge = '<span style="background:rgba(16,185,129,0.15); color:#10b981; border:1px solid rgba(16,185,129,0.3); font-size:0.72rem; font-weight:700; padding:2px 8px; border-radius:12px;">Đầy đủ kho</span>';
            if (catStock === 0) {
              statusBadge = '<span style="background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); font-size:0.72rem; font-weight:700; padding:2px 8px; border-radius:12px;">Hết hàng (0)</span>';
            } else if (catStock < 10) {
              statusBadge = '<span style="background:rgba(245,158,11,0.15); color:#f59e0b; border:1px solid rgba(245,158,11,0.3); font-size:0.72rem; font-weight:700; padding:2px 8px; border-radius:12px;">Sắp hết (' + catStock + ')</span>';
            }

            catRows += '<tr>' +
              '<td><strong style="color:#fff;"><i class="fa-solid fa-folder-closed" style="color:#38bdf8; margin-right:6px;"></i>' + escapeHtml(cat) + '</strong></td>' +
              '<td style="text-align:center;">' + prodsInCat.length + ' sản phẩm</td>' +
              '<td style="text-align:center; font-weight:700; color:#38bdf8;">' + catStock.toLocaleString("vi-VN") + ' acc</td>' +
              '<td style="text-align:center;">' + statusBadge + '</td>' +
              '<td style="text-align:right;">' +
                '<button class="btn-copy-small" onclick=\'switchAdminTab("tabAdmStock")\' style="font-size:0.72rem; padding:3px 8px;">Nạp Kho</button>' +
              '</td>' +
            '</tr>';
          });
          catTbody.innerHTML = catRows || '<tr><td colspan="5" style="text-align:center; color:#64748b;">Chưa có dữ liệu danh mục.</td></tr>';
        }

        // Đồng bộ lên thanh 4 chỉ số cũ trên đầu trang quản trị
        const statRev = document.getElementById("admStatRev");
        const statPaid = document.getElementById("admStatPaid");
        const statStock = document.getElementById("admStatStock");
        const statUsers = document.getElementById("admStatUsers");
        if (statRev) statRev.innerText = (typeof formatVND === "function") ? formatVND(totalGMV) : (totalGMV.toLocaleString("vi-VN") + " đ");
        if (statPaid) statPaid.innerText = successfulOrdersCount.toLocaleString("vi-VN");
        if (statStock) statStock.innerText = totalStockAccounts.toLocaleString("vi-VN");
        if (statUsers) statUsers.innerText = users.length;

      } catch(errOvw) {
        console.error("renderSystemOverview error:", errOvw);
      }
    }
    window.renderSystemOverview = renderSystemOverview;

    // ĐIỀU HƯỚNG PHÂN TRANG 10 ĐƠN/TRANG CHO 2 BẢNG QUẢN TRỊ TỔNG QUAN
    function buildOvwPaginationHtml(currentPage, totalItems, pageSize, onPageChangeFnName) {
      const totalPages = Math.ceil(totalItems / pageSize) || 1;
      if (totalPages <= 1) return "";

      let html = '<div style="display:flex; justify-content:center; align-items:center; gap:6px; margin-top:14px; padding:8px 0; flex-wrap:wrap; border-top:1px solid #1a2538;">';
      
      // Nút Trước
      if (currentPage > 1) {
        html += '<button type="button" onclick="' + onPageChangeFnName + '(' + (currentPage - 1) + ')" style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#cbd5e1; border-radius:6px; font-size:0.75rem; cursor:pointer;"><i class="fa-solid fa-chevron-left"></i> Trước</button>';
      } else {
        html += '<button type="button" disabled style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.75rem; cursor:not-allowed; opacity:0.6;"><i class="fa-solid fa-chevron-left"></i> Trước</button>';
      }

      // Các số trang
      for (let i = 1; i <= totalPages; i++) {
        if (i === currentPage) {
          html += '<button type="button" style="padding:4px 9px; background:#0284c7; border:1px solid #0284c7; color:#fff; font-weight:700; border-radius:6px; font-size:0.75rem;">' + i + '</button>';
        } else if (i === 1 || i === totalPages || (i >= currentPage - 1 && i <= currentPage + 1)) {
          html += '<button type="button" onclick="' + onPageChangeFnName + '(' + i + ')" style="padding:4px 9px; background:#0d131f; border:1px solid #1e293b; color:#94a3b8; border-radius:6px; font-size:0.75rem; cursor:pointer;">' + i + '</button>';
        } else if (i === currentPage - 2 || i === currentPage + 2) {
          html += '<span style="color:#64748b; padding:0 3px; font-size:0.75rem;">...</span>';
        }
      }

      // Nút Sau
      if (currentPage < totalPages) {
        html += '<button type="button" onclick="' + onPageChangeFnName + '(' + (currentPage + 1) + ')" style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#cbd5e1; border-radius:6px; font-size:0.75rem; cursor:pointer;">Sau <i class="fa-solid fa-chevron-right"></i></button>';
      } else {
        html += '<button type="button" disabled style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.75rem; cursor:not-allowed; opacity:0.6;">Sau <i class="fa-solid fa-chevron-right"></i></button>';
      }

      html += '<span style="font-size:0.72rem; color:#64748b; margin-left:6px;">(' + currentPage + '/' + totalPages + ' - ' + totalItems + ' mục)</span>';
      html += '</div>';
      return html;
    }
    window.buildOvwPaginationHtml = buildOvwPaginationHtml;

