    function handleAdmModalProviderChange() {
      const pSel = document.getElementById("admProdApiProvider");
      const sSel = document.getElementById("admProdApiSourceSelect");
      if (!pSel || !sSel) return;
      const provider = pSel.value || "sellmmo";
      const prods = (typeof cachedSourceProducts !== "undefined") ? cachedSourceProducts : [];
      const filtered = prods.filter(s => !s.provider || s.provider === provider);

      sSel.innerHTML = '<option value="">-- Chọn sản phẩm nguồn --</option>' + filtered.map(s => {
        return '<option value="' + s.id + '" data-price="' + s.price + '" data-stock="' + s.amount + '">' +
          '[' + escapeHtml(s.category || provider) + '] ' + escapeHtml(s.name) + ' - ' + formatVND(s.price) + ' (Tồn: ' + (s.amount || 0).toLocaleString() + ')' +
        '</option>';
      }).join("");

      handleAdmModalSourceChange();
    }
    window.handleAdmModalProviderChange = handleAdmModalProviderChange;

    function handleAdmModalSourceChange() {
      const sSel = document.getElementById("admProdApiSourceSelect");
      const info = document.getElementById("admProdApiSourceInfo");
      if (!sSel || !info) return;
      const opt = sSel.selectedOptions[0];
      if (opt && opt.value) {
        const price = opt.getAttribute("data-price") || 0;
        const stock = opt.getAttribute("data-stock") || 0;
        info.innerHTML = '<i class="fa-solid fa-circle-info"></i> Giá nhập gốc: <strong>' + formatVND(price) + '</strong> | Tồn kho live nguồn: <strong style="color:#10b981;">' + Number(stock).toLocaleString() + ' acc</strong>';
      } else {
        info.innerHTML = '<span style="color:#94a3b8;">Vui lòng chọn sản phẩm tương ứng từ nguồn API để khách mua sẽ được tự động cấp tài khoản.</span>';
      }
    }
    window.handleAdmModalSourceChange = handleAdmModalSourceChange;
  

    function openEditProductModal(id) {
      const delBtnEdit = document.getElementById("btnAdmDeleteProductModal"); if (delBtnEdit) delBtnEdit.style.display = "inline-flex";
      const cleanId = String(id || "").trim();
      const p = (MOCK_DATA && Array.isArray(MOCK_DATA.products))
        ? (MOCK_DATA.products.find(item => item && String(item.id) === cleanId) || 
           MOCK_DATA.products.find(item => item && String(item.id).toLowerCase() === cleanId.toLowerCase()))
        : null;
      if (!p) {
        showToast("Không tìm thấy thông tin sản phẩm (ID: " + id + ")!", "warning");
        return;
      }
      if (document.getElementById("admProdId")) document.getElementById("admProdId").value = p.id;
      if (document.getElementById("admProdName")) document.getElementById("admProdName").value = p.name;
      
      // Đồng bộ Loại Nguồn Hàng (Kho Nội Bộ vs API)
      const existingMap = (typeof getApiProductMapping === "function") ? getApiProductMapping(p.id) : null;
      const isApi = !!(existingMap && existingMap.enabled && existingMap.sourceProdId);
      const radioLocal = document.getElementById("admProdTypeLocal");
      const radioApi = document.getElementById("admProdTypeApi");
      if (radioLocal && radioApi) {
        radioLocal.checked = !isApi;
        radioApi.checked = isApi;
      }
      if (typeof toggleAdmProductSourceFields === "function") toggleAdmProductSourceFields();
      if (isApi && existingMap) {
        const pSel = document.getElementById("admProdApiProvider");
        if (pSel && existingMap.provider) {
          pSel.value = existingMap.provider;
          if (typeof handleAdmModalProviderChange === "function") handleAdmModalProviderChange();
        }
        const sSel = document.getElementById("admProdApiSourceSelect");
        if (sSel && existingMap.sourceProdId) {
          sSel.value = String(existingMap.sourceProdId);
          if (typeof handleAdmModalSourceChange === "function") handleAdmModalSourceChange();
        }
      }
      populateCategorySelects(p.category);
      if (document.getElementById("admProdPrice")) {
        document.getElementById("admProdPrice").value = p.price;
        document.getElementById("admProdPrice").oninput = function() {
          const varRows = document.querySelectorAll(".adm-variant-row");
          if (varRows.length === 1) {
            const vP = varRows[0].querySelector(".adm-variant-price");
            if (vP) vP.value = this.value;
          }
          if (typeof updateCommissionEstimate === "function") updateCommissionEstimate();
        };
      }
      if (document.getElementById("admProdCommission")) {
        const commMatch = (p.commission || "").match(/\d+/);
        document.getElementById("admProdCommission").value = commMatch ? commMatch[0] : "10";
      }
      if (document.getElementById("admProdBuffSold")) document.getElementById("admProdBuffSold").value = p.buffSold !== undefined ? p.buffSold : (p.sold || 0);
      if (document.getElementById("admProdBuffRating")) document.getElementById("admProdBuffRating").value = p.rating || "4.9";
      if (document.getElementById("admProdBuffReviews")) document.getElementById("admProdBuffReviews").value = p.reviewCount || 11;
      if (document.getElementById("admProdImage")) document.getElementById("admProdImage").value = p.image || "";
      if (document.getElementById("admProdImgPreview")) document.getElementById("admProdImgPreview").src = p.image || "https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@main/assets/images/chatgpt_plus.png";
      if (document.getElementById("admProdWarranty")) document.getElementById("admProdWarranty").value = p.warranty || "Bảo Hành 1 Đổi 1";
      if (document.getElementById("admProdDesc")) document.getElementById("admProdDesc").value = p.description || "";

      const variants = (p.variants && p.variants.length > 0) ? p.variants : [{ name: p.name, price: p.price }];
      renderVariantInputs(variants);

      updateCommissionEstimate();

      if (document.getElementById("admModalTitle")) document.getElementById("admModalTitle").innerHTML = '<i class="fa-solid fa-pen-to-square green"></i> Sửa Sản Phẩm: ' + escapeHtml(p.name);
      const modal = document.getElementById("adminProductModal");
      if (modal) modal.style.display = "flex";
    }
